
const feed = document.getElementById("feed");
const postInput = document.getElementById("postInput");
const publishBtn = document.getElementById("publishBtn");
const searchInput = document.getElementById("searchInput");

// CRIAR PUBLICAÇÃO

function createPost(text) {
    const post = document.createElement("article");
        post.className = "post";

            const header = document.createElement("div");
                header.className = "post-header";

                    header.innerHTML = `
                            <div class="user-info">
                                        <div class="avatar">G</div>
                                                    <div>
                                                                    <strong>goober123</strong>
                                                                                    <small>Agora mesmo</small>
                                                                                                </div>
                                                                                                        </div>
                                                                                                                <button class="more-btn">•••</button>
                                                                                                                    `;

                                                                                                                        const content = document.createElement("div");
                                                                                                                            content.className = "post-content";

                                                                                                                                const paragraph = document.createElement("p");
                                                                                                                                    paragraph.innerHTML = "<strong>goober123</strong> ";
                                                                                                                                        paragraph.appendChild(document.createTextNode(text));

                                                                                                                                            const actions = document.createElement("div");
                                                                                                                                                actions.className = "post-actions";

                                                                                                                                                    actions.innerHTML = `
                                                                                                                                                            <button class="like-btn">♡</button>
                                                                                                                                                                    <button class="comment-btn">▢</button>
                                                                                                                                                                            <button>↗</button>
                                                                                                                                                                                    <button class="save-btn">♧</button>
                                                                                                                                                                                        `;

                                                                                                                                                                                            const likes = document.createElement("strong");
                                                                                                                                                                                                likes.className = "likes";
                                                                                                                                                                                                    likes.textContent = "0 curtidas";

                                                                                                                                                                                                        const commentCount = document.createElement("small");
                                                                                                                                                                                                            commentCount.className = "comment-count";
                                                                                                                                                                                                                commentCount.textContent = "Adicionar comentário";

                                                                                                                                                                                                                    content.append(actions, likes, paragraph, commentCount);
                                                                                                                                                                                                                        post.append(header, content);

                                                                                                                                                                                                                            feed.prepend(post);
                                                                                                                                                                                                                            }

                                                                                                                                                                                                                            // BOTÃO PUBLICAR

                                                                                                                                                                                                                            publishBtn.addEventListener("click", () => {
                                                                                                                                                                                                                                const text = postInput.value.trim();

                                                                                                                                                                                                                                    if (!text) {
                                                                                                                                                                                                                                            alert("Escreva algo antes de publicar!");
                                                                                                                                                                                                                                                    return;
                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                            createPost(text);
                                                                                                                                                                                                                                                                postInput.value = "";
                                                                                                                                                                                                                                                                });

                                                                                                                                                                                                                                                                // CURTIDAS

                                                                                                                                                                                                                                                                feed.addEventListener("click", (event) => {
                                                                                                                                                                                                                                                                    const like = event.target.closest(".like-btn");

                                                                                                                                                                                                                                                                        if (like) {
                                                                                                                                                                                                                                                                                like.classList.toggle("liked");

                                                                                                                                                                                                                                                                                        const post = like.closest(".post");
                                                                                                                                                                                                                                                                                                const likes = post.querySelector(".likes");

                                                                                                                                                                                                                                                                                                        let count = Number(
                                                                                                                                                                                                                                                                                                                    likes.dataset.count || 0
                                                                                                                                                                                                                                                                                                                            );

                                                                                                                                                                                                                                                                                                                                    count += like.classList.contains("liked") ? 1 : -1;

                                                                                                                                                                                                                                                                                                                                            likes.dataset.count = count;
                                                                                                                                                                                                                                                                                                                                                    likes.textContent = count + " curtidas";

                                                                                                                                                                                                                                                                                                                                                            like.textContent =
                                                                                                                                                                                                                                                                                                                                                                        like.classList.contains("liked") ? "♥" : "♡";
                                                                                                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                                                                                                // SALVAR PUBLICAÇÃO

                                                                                                                                                                                                                                                                                                                                                                                    const save = event.target.closest(".save-btn");

                                                                                                                                                                                                                                                                                                                                                                                        if (save) {
                                                                                                                                                                                                                                                                                                                                                                                                save.classList.toggle("saved");

                                                                                                                                                                                                                                                                                                                                                                                                        save.textContent =
                                                                                                                                                                                                                                                                                                                                                                                                                    save.classList.contains("saved") ? "◆" : "♧";
                                                                                                                                                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                                                                                                                                                            // COMENTÁRIOS

                                                                                                                                                                                                                                                                                                                                                                                                                                const comment = event.target.closest(".comment-btn");

                                                                                                                                                                                                                                                                                                                                                                                                                                    if (comment) {
                                                                                                                                                                                                                                                                                                                                                                                                                                            const post = comment.closest(".post");
                                                                                                                                                                                                                                                                                                                                                                                                                                                    const content = post.querySelector(".post-content");

                                                                                                                                                                                                                                                                                                                                                                                                                                                            let input = content.querySelector(".comment-input");

                                                                                                                                                                                                                                                                                                                                                                                                                                                                    if (input) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                input.focus();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            return;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            input = document.createElement("input");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    input.className = "comment-input";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            input.placeholder = "Escreva um comentário...";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    input.style.cssText =
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                "width:100%;padding:12px;margin-top:12px;border:1px solid #e5efec;border-radius:10px;outline:none;";

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        content.appendChild(input);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                input.addEventListener("keydown", (e) => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            if (e.key === "Enter" && input.value.trim()) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            const newComment = document.createElement("p");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            newComment.textContent =
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                "Você: " + input.value.trim();

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                content.insertBefore(newComment, input);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                input.value = "";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                input.remove();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    });

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            input.focus();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                });

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                // PESQUISAR POSTS

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                searchInput.addEventListener("input", () => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    const search = searchInput.value.toLowerCase();

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        document.querySelectorAll(".post").forEach(post => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                const content = post.textContent.toLowerCase();

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        post.style.display =
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    content.includes(search) ? "" : "none";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        });

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        // NAVEGAÇÃO

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        document.querySelectorAll(".nav-item").forEach(item => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            item.addEventListener("click", (event) => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    event.preventDefault();

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            document.querySelectorAll(".nav-item")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        .forEach(link => link.classList.remove("active"));

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                item.classList.add("active");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    });

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    // BOTÕES SEGUIR

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    document.querySelectorAll(".suggestion button").forEach(button => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        button.addEventListener("click", () => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                const following = button.textContent === "Seguindo";

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        button.textContent = following ? "Seguir" : "Seguindo";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            });

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            // STORIES

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            document.querySelectorAll(".story").forEach(story => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                story.addEventListener("click", () => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        alert("Story selecionado! 🫧");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            